"""Rule-based task classifier: request -> quality floor (task type + minimum level).

Deliberately simple and explainable. The harness can always override it with
``X-Route-Floor: coding:4`` or nudge it with ``X-Route-Hint: cheap|smart``.
A learned router (RouteLLM-style) can replace this later behind the same interface.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

from .formats.translate import text_of
from .sessions import est_tokens

_CODE_HINTS = re.compile(
    r"```|\bdef |\bclass |\bimport |\bfunction\b|\bconst |=>|Traceback|stack trace|\.py\b|\.ts\b|\.go\b|\.rs\b|\.java\b|"
    r"\bcompile|\brefactor|\bunit test|\bbug\b|\bregex\b|\bSQL\b",
    re.IGNORECASE,
)
_HARD_HINTS = re.compile(
    r"\barchitect|\bdesign (a|the)|\brace condition|\bdeadlock|\bsecurity|\bvulnerab|\bprove\b|\bmigrat|\bperformance|"
    r"\boptimi[sz]e|\bconcurren|\bdistributed",
    re.IGNORECASE,
)
_ANALYSIS_HINTS = re.compile(r"\banaly[sz]e|\bcompare|\bstrategy|\bplan\b|\btrade-?offs?|\bevaluate|\breason", re.IGNORECASE)


@dataclass
class Floor:
    task: str
    level: int
    reason: str

    def __str__(self) -> str:
        return f"{self.task}:{self.level}"


def parse_floor(value: str) -> Floor | None:
    m = re.fullmatch(r"\s*([a-z_]+)\s*:\s*([1-5])\s*", value or "")
    return Floor(m.group(1), int(m.group(2)), "header") if m else None


def _recent_user_text(body: dict, n: int = 2) -> str:
    texts = []
    for m in reversed(body.get("messages") or []):
        if m.get("role") == "user":
            texts.append(text_of(m.get("content")))
            if len(texts) >= n:
                break
    return "\n".join(texts)[:20000]


def classify(body: dict, headers: dict[str, str]) -> Floor:
    explicit = parse_floor(headers.get("x-route-floor", ""))
    if explicit:
        return explicit

    tools = body.get("tools") or []
    text = _recent_user_text(body)
    size = est_tokens(body)
    coding = bool(tools) or bool(_CODE_HINTS.search(text))

    if coding:
        level, reason = 3, "coding"
        if tools and len(tools) >= 5:
            level, reason = 4, "agentic coding (many tools)"
        if _HARD_HINTS.search(text) or size > 60_000:
            level, reason = min(level + 1, 5), reason + ", hard task or large context"
        task = "coding"
    else:
        task = "general"
        level, reason = 2, "general"
        if size < 400 and not tools:
            level, reason = 1, "short question"
        if _ANALYSIS_HINTS.search(text) or size > 20_000:
            level, reason = 3, "analysis or long context"

    hint = (headers.get("x-route-hint") or "").lower()
    if hint == "cheap":
        level, reason = level - 1, reason + ", hint=cheap"
    elif hint == "smart":
        level, reason = level + 1, reason + ", hint=smart"
    return Floor(task, max(1, min(5, level)), reason)

