        (BO, None, 0), ("key", "a", 1), (BA, None, 6), ("number", 1, 7), ("bool", True, 10), ("null", None, 16),
        (EA, None, 20), ("key", "b", 23), (BO, None, 28), ("key", "c", 29), ("string", "d", 34), (EO, None, 37),
        (EO, None, 38),
    ]


