    assert _whole('{"k": "v", "list": ["k", {"x": "y"}]}') == [
        (BO, None, 0), ("key", "k", 1), ("string", "v", 6), ("key", "list", 11), (BA, None, 19), ("string", "k", 20),
        (BO, None, 25), ("key", "x", 26), ("string", "y", 31), (EO, None, 34), (EA, None, 35), (EO, None, 36),
