        for i in range(len(doc) + 1):
            t = Tokenizer()
            if i <= k:
                t.feed(doc[:i])  # must not raise yet
                try:
                    t.feed(doc[i:])
                except JSONStreamError as e:
                    assert e.offset == k, (doc, i)
                else:
