"""Deterministic compression of large tool outputs (docs/04-caching-and-sessions.md).

Rules:
* Only tool results, only when they're large. Never user or assistant text.
* Deterministic: the same input always produces the same output, so applying it
  to every tool result in the history on every turn keeps the prompt prefix
  byte-stable and provider caches keep hitting. Nothing is stored.
* Changing the settings mid-session changes the history once (one cache miss).
"""

from __future__ import annotations

import re
from dataclasses import dataclass

from pydantic import BaseModel

_ANSI = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]|\x1b\][^\x07]*\x07")
_TRAILING_WS = re.compile(r"[ \t]+\n")
_BLANKS = re.compile(r"\n{3,}")


class CompressionConfig(BaseModel):
    enabled: bool = False
    min_chars: int = 4000  # leave anything shorter alone
    max_chars: int = 24000  # beyond this, keep the head and tail
    head_fraction: float = 0.6


@dataclass
class Result:
    removed_chars_new: int = 0  # from tool results in the newest message (would be billed as fresh input)
    removed_chars_history: int = 0  # from earlier tool results (would mostly be cache reads)

    @property
    def removed_tokens_new(self) -> int:
        return self.removed_chars_new // 4

    @property
    def removed_tokens_history(self) -> int:
        return self.removed_chars_history // 4


def compress_text(text: str, cfg: CompressionConfig) -> str:
    if len(text) < cfg.min_chars:
        return text
    out = _ANSI.sub("", text)
    out = _TRAILING_WS.sub("\n", out)
    out = _BLANKS.sub("\n\n", out)
    # Collapse runs of identical lines (progress bars, repeated log lines).
    lines = out.split("\n")
    collapsed: list[str] = []
    i = 0
    while i < len(lines):
        j = i
        while j + 1 < len(lines) and lines[j + 1] == lines[i]:
            j += 1
        run = j - i + 1
        collapsed.append(lines[i] if run < 3 else f"{lines[i]}\n[previous line repeated {run - 1} more times]")
        i = j + 1
    out = "\n".join(collapsed)
    if len(out) > cfg.max_chars:
        head = int(cfg.max_chars * cfg.head_fraction)
        tail = cfg.max_chars - head
        omitted = out[head : len(out) - tail]
        out = (
            out[:head]
            + f"\n[... {omitted.count(chr(10)) + 1} lines, {len(omitted)} characters omitted by Merit Order ...]\n"
            + out[len(out) - tail :]
        )
    return out


def _compress_value(value, cfg: CompressionConfig) -> tuple[object, int]:
    """Compress a tool result's content (string or list of text blocks). Returns (new value, chars removed)."""
    if isinstance(value, str):
        new = compress_text(value, cfg)
        return new, len(value) - len(new)
    if isinstance(value, list):
        removed = 0
        out = []
        for block in value:
            if isinstance(block, dict) and block.get("type") == "text" and isinstance(block.get("text"), str):
                new = compress_text(block["text"], cfg)
                removed += len(block["text"]) - len(new)
                block = {**block, "text": new} if new != block["text"] else block
            out.append(block)
        return out, removed
    return value, 0


def compress_tool_results(body: dict, fmt: str, cfg: CompressionConfig) -> tuple[dict, Result]:
    """Returns a (shallow-copied where changed) body with large tool results compressed."""
    result = Result()
    if not cfg.enabled:
        return body, result
    messages = body.get("messages") or []
    new_messages = []
    last = len(messages) - 1
    for idx, m in enumerate(messages):
        changed = m
        if fmt == "openai" and m.get("role") == "tool":
            content, removed = _compress_value(m.get("content"), cfg)
            if removed:
                changed = {**m, "content": content}
                if idx == last:
                    result.removed_chars_new += removed
                else:
                    result.removed_chars_history += removed
        elif fmt == "anthropic" and m.get("role") == "user" and isinstance(m.get("content"), list):
            blocks = []
            any_change = False
            for b in m["content"]:
                if isinstance(b, dict) and b.get("type") == "tool_result":
                    content, removed = _compress_value(b.get("content"), cfg)
                    if removed:
                        b = {**b, "content": content}
                        any_change = True
                        if idx == last:
                            result.removed_chars_new += removed
                        else:
                            result.removed_chars_history += removed
                blocks.append(b)
            if any_change:
                changed = {**m, "content": blocks}
        new_messages.append(changed)
    if result.removed_chars_new or result.removed_chars_history:
        body = {**body, "messages": new_messages}
    return body, result

