"""Configuration stored in Postgres: versions, validation, hot reload.

The YAML file is the starting point. Once an admin saves a configuration from the
console, versions live in Postgres (who, when, why) and every gateway applies the
newest one within seconds. Secrets never go in: they stay in environment
variables, referenced as ${NAME}.
"""

from __future__ import annotations

import logging
import re
from pathlib import Path
from typing import Any

import yaml

from .config import Config, build_config, effort_format

log = logging.getLogger("meritorder.configstore")

_ENV_REF = re.compile(r"^\$\{[A-Za-z_][A-Za-z0-9_]*(?::-[^}]*)?\}$")


class ConfigError(Exception):
    pass


def secret_problems(raw: dict) -> list[str]:
    """Literal secrets in the document (they must be ${ENV} references instead)."""
    problems = []
    for name, b in (raw.get("backends") or {}).items() if isinstance(raw.get("backends"), dict) else []:
        value = ((b or {}).get("auth") or {}).get("value")
        if value and not _ENV_REF.match(str(value)):
            problems.append(f"backends.{name}.auth.value holds a literal secret; use value_env or ${{NAME}}")
    for i, k in enumerate(((raw.get("auth") or {}).get("static_keys")) or []):
        if (k or {}).get("key") and not _ENV_REF.match(str(k["key"])):
            problems.append(f"auth.static_keys[{i}].key holds a literal key; use key_env")
    problems.extend(_secret_refs(raw, ""))
    return problems


# ${NAME} is expanded anywhere in the document, and the expanded config is readable by admins. So a
# secret-looking variable may only be referenced where a secret belongs; elsewhere (say, a base_url) it
# would show the database password or SCIM token to anyone who can read the config.
_SECRETISH = re.compile(r"KEY|TOKEN|SECRET|PASSW|CREDENTIAL|DATABASE_URL|REDIS_URL|DSN", re.I)
_ENV_ANY = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)")
_SECRET_PLACES = re.compile(r"^backends\.[^.]+\.auth\.value$|^auth\.static_keys\[\d+\]\.key$")


def _secret_refs(value: Any, path: str) -> list[str]:
    if isinstance(value, dict):
        return [p for k, v in value.items() for p in _secret_refs(v, f"{path}.{k}" if path else str(k))]
    if isinstance(value, list):
        return [p for i, v in enumerate(value) for p in _secret_refs(v, f"{path}[{i}]")]
    if isinstance(value, str) and not _SECRET_PLACES.match(path):
        return [f"{path} references ${{{name}}}, which looks like a secret; secrets belong in auth (value_env, value_file, or key_env)"
                for name in _ENV_ANY.findall(value) if _SECRETISH.search(name)]
    return []


def prune(value: Any) -> Any:
    """Drop empty values (None, "", {}, []) so blank form fields mean "use the default"."""
    if isinstance(value, dict):
        out = {k: prune(v) for k, v in value.items()}
        return {k: v for k, v in out.items() if v is not None and v != "" and v != {} and not (isinstance(v, list) and not v and k != "routes")}
    if isinstance(value, list):
        return [prune(v) for v in value]
    return value


def parse_document(text: str | None = None, document: dict | None = None) -> dict:
    if document is not None:
        raw = document
    else:
        try:
            raw = yaml.safe_load(text or "")
        except yaml.YAMLError as e:
            raise ConfigError(f"not valid YAML: {e}")
    if not isinstance(raw, dict):
        raise ConfigError("the configuration must be a mapping")
    return prune(raw)


def parse_and_validate(text: str | None, config_dir: str, prices: dict | None, document: dict | None = None) -> tuple[dict, Config]:
    raw = parse_document(text, document)
    if not isinstance(raw, dict):
        raise ConfigError("the configuration must be a YAML mapping")
    if "include" in raw:
        raise ConfigError("`include:` isn't supported in stored configurations; paste the included sections in")
    problems = secret_problems(raw)
    if problems:
        raise ConfigError("; ".join(problems))
    try:
        cfg = build_config(raw, config_dir, prices_data=prices, quiet=True)
    except Exception as e:  # pydantic validation errors and friends
        raise ConfigError(str(e))
    return raw, cfg


def summarize(cfg: Config) -> dict[str, Any]:
    return {
        "backends_enabled": sorted(b.name for b in cfg.backends if b.enabled),
        "backends_disabled": {b.name: b.disabled_reason or "disabled in config" for b in cfg.backends if not b.enabled},
        "models": len([m for m in cfg.models if m.kind == "chat"]),
        "embedding_models": len([m for m in cfg.models if m.kind == "embedding"]),
        "unpriced_routes": sorted(f"{m.name}@{r.backend}" for m in cfg.models for r in m.routes if not r.priced),
        "teams": [t.name for t in cfg.teams],
        "effort": {b.name: effort_format(b) for b in cfg.backends if b.enabled},
    }


def to_yaml(raw: dict) -> str:
    return yaml.safe_dump(raw, sort_keys=False, allow_unicode=True, width=120)


def token(version: int | None, prices: dict | None) -> str:
    """Changes whenever the stored configuration, prices or quality scores change."""
    return f"{version or 'file'}:{(prices or {}).get('updated', '')}:{((prices or {}).get('quality') or {}).get('updated', '')}"


async def load_active(gw, publish: bool = False) -> bool:
    """Apply the newest stored configuration and prices unless already applied. Returns True if applied."""
    row = await gw.store.active_config()
    prices = await gw.store.get_setting("prices")
    tok = token(row["id"] if row else None, prices)
    if tok == getattr(gw, "config_token", None):
        return False
    if row is None and prices is None:
        gw.config_token = tok  # nothing stored: the YAML file stays in effect
        return False
    raw = row["body"] if row else gw.file_raw
    if raw is None:
        return False
    cfg = build_config(raw, gw.file_cfg.config_dir, prices_data=prices)
    await gw.apply_config(cfg, row["id"] if row else None)
    gw.config_token = tok
    if publish:
        await gw.state.set_config_token(tok)
    return True


class ConfigFollower:
    """The active configuration for processes without a gateway (worker, controller), reloaded when it changes.

    Without this they would keep using the YAML file and miss budgets and safeguards edited in the console.
    """

    def __init__(self, store, path=None, cfg=None):
        from .config import default_config_path, load_raw_config

        self.store = store
        if cfg is not None:
            self.file_raw, self.file_cfg = None, cfg
        else:
            p = Path(path) if path else default_config_path()
            self.file_raw = load_raw_config(p)
            self.file_cfg = build_config(self.file_raw, p.parent)
        self.cfg = self.file_cfg
        self.token: str | None = None

    async def current(self):
        row = await self.store.active_config()
        prices = await self.store.get_setting("prices")
        tok = token(row["id"] if row else None, prices)
        if tok == self.token:
            return self.cfg
        raw = row["body"] if row else self.file_raw
        if raw is not None and (row is not None or prices is not None):
            try:
                self.cfg = build_config(raw, self.file_cfg.config_dir, prices_data=prices, quiet=True)
                log.info("using configuration version %s", row["id"] if row else "file (stored prices)")
            except Exception:
                log.exception("stored configuration doesn't load; keeping the previous one")
        self.token = tok
        return self.cfg

69c4f0da9c971991:
"""FastAPI application: OpenAI and Anthropic compatible endpoints plus reports and auth."""

from __future__ import annotations

import asyncio
import logging
import os
import socket
from pathlib import Path
from contextlib import asynccontextmanager

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse, PlainTextResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles

from . import __version__
from .auth import Authenticator, AuthError
from .backends import build_backends
from .config import Config, build_config, default_config_path, load_raw_config
from .configstore import load_active
from .proxy import Gateway
from .admin import build_router as build_admin_router
from .console import build_router as build_console_router
from .scim import build_router as build_scim_router
from .controls import build_router as build_controls_router
from .telemetry import setup_tracing
from .reports import build_router as build_reports_router
from .router import Router
from .state import make_state
from .store import make_store

log = logging.getLogger("meritorder")


def build_gateway(cfg: Config, store=None, state=None) -> Gateway:
    store = store or make_store(os.environ.get("MERITORDER_DATABASE_URL"))
    state = state or make_state(os.environ.get("MERITORDER_REDIS_URL"))
    backends = build_backends(cfg)
    return Gateway(cfg, store, state, backends, Router(cfg, backends), Authenticator(cfg, store))


def create_app(cfg: Config | None = None, gateway: Gateway | None = None) -> FastAPI:
    raw = None
    if cfg is None and gateway is None:
        path = default_config_path()
        raw = load_raw_config(path)
        cfg = build_config(raw, path.parent)
    cfg = cfg or gateway.cfg
    gw = gateway or build_gateway(cfg)
    gw.file_raw = raw if raw is not None else getattr(gw, "file_raw", None)

    @asynccontextmanager
    async def lifespan(app: FastAPI):
        setup_tracing()
        await gw.store.init()
        if gw.store.kind == "memory":
            log.warning("no MERITORDER_DATABASE_URL set: using in-memory storage (data is lost on restart)")
        try:
            await load_active(gw)
        except Exception:
            log.exception("could not load the stored configuration; using the YAML file")
        enabled = sorted(gw.backends)
        log.info("Merit Order %s ready; backends: %s", __version__, ", ".join(enabled) or "(none)")
        gateway_id = f"{socket.gethostname()}-{os.getpid()}"

        async def follow_controller():
            while True:
                try:
                    await gw.state.heartbeat(gateway_id)
                    stored = await gw.state.get_config_token()
                    if stored is not None and stored != getattr(gw, "config_token", None):
                        await load_active(gw)
                    await gw.refresh_deployments()
                except Exception:
                    log.exception("could not refresh configuration or deployments")
                await asyncio.sleep(5)

        follower = asyncio.create_task(follow_controller())
        yield
        follower.cancel()
        await gw.drain()
        for b in gw.backends.values():
            await b.close()
        await gw.state.close()
        await gw.store.close()

    app = FastAPI(title="Merit Order", version=__version__, lifespan=lifespan)
    app.state.gateway = gw

    @app.post("/v1/chat/completions")
    async def chat_completions(request: Request):
        return await gw.handle(request, "openai")

    @app.post("/v1/responses")
    async def responses(request: Request):
        return await gw.handle(request, "openai", wire="responses")

    @app.post("/v1/embeddings")
    async def embeddings(request: Request):
        return await gw.embeddings(request)

    @app.post("/v1/messages")
    async def messages(request: Request):
        return await gw.handle(request, "anthropic")

    @app.post("/v1/messages/count_tokens")
    async def count_tokens(request: Request):
        return await gw.count_tokens(request)

    @app.get("/v1/models")
    async def models(request: Request):
        try:
            p = await gw.authn.authenticate({k.lower(): v for k, v in request.headers.items()})
        except AuthError as e:
            raise HTTPException(e.status, e.message)
        cfg = gw.cfg
        team = cfg.team(p.team)
        usable = [m for m in cfg.models if team.allows_model(m.name) and any(r.backend in gw.backends for r in m.routes)]
        if any(r.backend in gw.backends and gw.backends[r.backend].kind != "mock" for m in usable for r in m.routes):
            usable = [m for m in usable if any(gw.backends[r.backend].kind != "mock" for r in m.routes if r.backend in gw.backends)]
        auto_ctx = max((m.context_window for m in usable if m.context_window), default=None)
        data = [{"id": cfg.routing.auto_model, "object": "model", "created": 0, "owned_by": "meritorder", "context_window": auto_ctx}]
        data += [{"id": m.name, "object": "model", "created": 0, "owned_by": "meritorder", "context_window": m.context_window,
                  "quality": m.quality, "type": m.kind, "self_hostable": bool(m.hf_id)} for m in usable]
        return {"object": "list", "data": data}

    @app.get("/metrics")
    async def metrics(request: Request):
        token = os.environ.get("MERITORDER_METRICS_TOKEN")
        if token and request.headers.get("authorization") != f"Bearer {token}":
            raise HTTPException(401, "metrics token required")
        return PlainTextResponse(gw.metrics.render(), media_type="text/plain; version=0.0.4")

    @app.get("/healthz")
    async def healthz():
        return {"status": "ok", "version": __version__}

    @app.get("/readyz")
    async def readyz():
        try:
            ok = await gw.store.ping() and await gw.state.ping()
        except Exception as e:
            return JSONResponse({"status": "unavailable", "error": str(e)}, status_code=503)
        return {"status": "ok" if ok else "unavailable", "backends": sorted(gw.backends)}

    @app.get("/auth/config")
    async def auth_config():
        o = gw.cfg.auth.oidc
        if not o:
            return {"oidc": None}
        return {"oidc": {"issuer": o.issuer, "client_id": o.client_id, "scopes": o.scopes}}

    @app.post("/auth/exchange")
    async def auth_exchange(request: Request):
        body = await request.json()
        try:
            return await gw.authn.exchange(str(body.get("id_token") or ""))
        except AuthError as e:
            raise HTTPException(e.status, e.message)

    app.include_router(build_reports_router(gw))
    app.include_router(build_admin_router(gw))
    app.include_router(build_console_router(gw))
    app.include_router(build_scim_router(gw))
    app.include_router(build_controls_router(gw))

    ui_dir = Path(__file__).parent / "ui_dist"
    if (ui_dir / "index.html").exists():
        app.mount("/ui", StaticFiles(directory=ui_dir, html=True), name="ui")

        @app.get("/", include_in_schema=False)
        async def root():
            return RedirectResponse("/ui/")
    return app

