"""Prompt shaping that makes provider cache hits likely without rewriting history.

Rules (see docs/04-caching-and-sessions.md):
* Never change earlier turns. Anything we add goes at the top level or the end.
* If the client already placed cache breakpoints, leave caching to the client.
"""

from __future__ import annotations

from typing import Any

from .config import BackendConfig


def _has_cc(value: Any) -> bool:
    if isinstance(value, dict):
        if "cache_control" in value:
            return True
        return any(_has_cc(v) for k, v in value.items() if k in ("content", "system", "tools", "messages"))
    if isinstance(value, list):
        return any(_has_cc(v) for v in value)
    return False


def has_cache_control(body: dict) -> bool:
    if body.get("cache_control"):
        return True
    return _has_cc(body.get("tools")) or _has_cc(body.get("system")) or _has_cc(body.get("messages"))


def shape_anthropic(body: dict, backend: BackendConfig) -> bool:
    """Turn on automatic prompt caching when the client hasn't set any breakpoints.

    Returns True when Merit Order added caching (counts toward caching savings).
    Automatic caching places one breakpoint on the last cacheable block and moves
    it forward as the conversation grows, which is exactly the agent-loop pattern.
    """
    if has_cache_control(body):
        return False
    cc: dict[str, Any] = {"type": "ephemeral"}
    if backend.cache_ttl_seconds >= 3600:
        cc["ttl"] = "1h"
    body["cache_control"] = cc
    return True


def shape_openai(body: dict, backend: BackendConfig, session_id: str) -> bool:
    """OpenAI-style caching is automatic; a stable cache key improves hit rates.

    Returns False: the provider caches with or without us, so no savings are claimed.
    """
    if backend.supports_prompt_cache_key and "prompt_cache_key" not in body:
        body["prompt_cache_key"] = session_id[:64]
    return False

76431230f2c77015:
"""Keeping prices live: the worker refreshes them from the live lists every ``prices_refresh_minutes``.

Gateways reload when the stored prices change, so a refresh that finds nothing new changes nothing. A list that
can't be fetched keeps its routes' last prices (and raises an alert); a price that changes, or a direct-API price
that disagrees with OpenRouter's for the same model, is reported on the console and to the alert webhook.
"""

from __future__ import annotations

import asyncio
import logging
from datetime import UTC, datetime

from . import alerts
from .catalog import price_source, refresh_prices
from .config import Config
from .configstore import token

log = logging.getLogger("meritorder.prices")

FIELDS = ("input", "output", "cache_read", "cache_write")
PRICE_SECTIONS = ("prices", "context", "max_output", "reasoning")


def _fmt(p: dict | None) -> str:
    return "none" if not p else f"${p.get('input', 0):g}/${p.get('output', 0):g}"


def changes(old: dict, new: dict) -> list[str]:
    """What changed between two price lists, in words: "openrouter:x/y $0.3/$1.2 -> $0.05/$0.57"."""
    out = []
    for key in sorted(set(old) | set(new)):
        a, b = old.get(key), new.get(key)
        if a is None or b is None:
            out.append(f"{key}: {_fmt(a)} -> {_fmt(b)}")
        elif any(a.get(f) != b.get(f) for f in FIELDS) or a.get("tiers") != b.get("tiers"):
            out.append(f"{key}: {_fmt(a)} -> {_fmt(b)}" + (" (long-prompt prices changed)" if a.get("tiers") != b.get("tiers") else ""))
    return out


def keep_unfetched(cfg: Config, old: dict, data: dict) -> None:
    """A list that couldn't be fetched keeps its routes' previous prices (and limits), rather than leaving them unpriced."""
    failed = {name for name, s in data.get("sources", {}).items() if not s.get("ok")}
    if not failed or not old:
        return
    kinds = {b.name: price_source(b)[0] for b in cfg.backends}
    for key, price in (old.get("prices") or {}).items():
        source = price.get("source") or kinds.get(key.split(":", 1)[0], "openrouter")
        if source in failed and key not in data["prices"]:
            data["prices"][key] = price
    for section in ("context", "max_output"):
        for k, v in (old.get(section) or {}).items():
            data.setdefault(section, {}).setdefault(k, v)
    data["reasoning"] = sorted(set(data.get("reasoning") or []) | set(old.get("reasoning") or [])) if "openrouter" in failed else data.get("reasoning", [])


async def refresh_once(cfg: Config, store, state, fetch=refresh_prices) -> dict:
    """One refresh: fetch, store if anything changed, alert, and record when it last checked (``prices_status``)."""
    _, priced, missing, data = await asyncio.to_thread(fetch, cfg, None, False)
    old = await store.get_setting("prices") or {}
    keep_unfetched(cfg, old, data)
    if old.get("quality"):
        data["quality"] = old["quality"]  # quality scores share the stored catalog; they're refreshed on their own schedule
    changed = changes(old.get("prices") or {}, data["prices"]) if old else []
    if not old or changed or any(old.get(s) != data.get(s) for s in PRICE_SECTIONS):
        await store.set_setting("prices", data)
        # Gateways reload when the configuration token changes; it covers the stored prices too.
        row = await store.active_config()
        await state.set_config_token(token(row["id"] if row else None, data))
    if old and changed:
        shown = "; ".join(changed[:8]) + (f"; and {len(changed) - 8} more" if len(changed) > 8 else "")
        await alerts.notify(f"Prices changed ({len(changed)}): {shown}", state=state, title="Prices changed", level="info", page="models")
    for d in data.get("disagreements", []):
        if await alerts._once(state, f"alert:price-disagree:{d['model']}:{d['backend']}:{d['field']}:{d['listed']}:{d['openrouter']}", 86400):
            await alerts.notify(f"{d['model']} on {d['backend']}: the provider's list price for {d['field']} is ${d['listed']:g} per million tokens, "
                                f"but OpenRouter charges ${d['openrouter']:g}. One of the price lists is probably wrong or stale: check the "
                                "provider's pricing page, and set the route's price in the config if the list is wrong.",
                                state=state, title=f"Prices disagree for {d['model']}", level="warning", page="models")
    for name, s in data.get("sources", {}).items():
        if not s.get("ok") and await alerts._once(state, f"alert:price-source:{name}", 6 * 3600):
            await alerts.notify(f"Couldn't refresh prices from {name} ({s.get('error')}); routing keeps the last prices it had.",
                                state=state, title=f"Price list unavailable: {name}", level="warning", page="models")
    status = {"checked_at": datetime.now(UTC).isoformat(timespec="seconds"), "sources": data.get("sources", {}),
              "disagreements": data.get("disagreements", []), "missing": missing, "priced_routes": priced, "changed": changed[:50]}
    await store.set_setting("prices_status", status)
    if changed:
        log.info("prices changed: %s", "; ".join(changed[:20]))
    return status


class PriceRefresher:
    """Calls ``refresh_once`` when ``prices_refresh_minutes`` have passed (and on the first call)."""

    def __init__(self) -> None:
        self.last = 0.0

    async def maybe(self, cfg: Config, store, state, now: float, fetch=refresh_prices) -> dict | None:
        if self.last and now - self.last < cfg.prices_refresh_minutes * 60:
            return None
        self.last = now
        try:
            return await refresh_once(cfg, store, state, fetch)
        except Exception:  # noqa: BLE001 (a bad refresh must not stop the worker; prices stay as they were)
            log.exception("price refresh failed")
            return None

79d79f00a0af0335:
"""Catching provider failures that arrive after a 200, so the request can still go to another source.

Anthropic reports overload inside a stream that has already started (``event: error`` with
``overloaded_error``), and OpenAI-compatible providers (OpenRouter in particular) send ``{"error": ...}``
chunks, or a 200 JSON body that is only an error. Nothing has reached the client at that point, so the
gateway reads the start of each stream (up to its first content) before committing to it, and turns these
into a :class:`BackendError` the fallback loop handles like any other failure.
"""

from __future__ import annotations

import asyncio
import time

import httpx

from .backends.base import BackendError, UpstreamResponse
from .formats.sse import SSEEvent

_TYPE_STATUS = {"overloaded_error": 529, "rate_limit_error": 429, "api_error": 500, "server_error": 500, "timeout_error": 504,
                "service_unavailable": 503, "service_unavailable_error": 503, "insufficient_quota": 429, "not_found_error": 404,
                "authentication_error": 401, "permission_error": 403, "invalid_request_error": 400}
_PEEK_LIMIT = 200  # events; a stream that hasn't shown content by then is committed to anyway


def _status(err: dict) -> int:
    code = err.get("code")
    if isinstance(code, int) and 400 <= code < 600:
        return code
    if isinstance(code, str) and code.isdigit() and 400 <= int(code) < 600:
        return int(code)
    for key in ("type", "code"):
        status = _TYPE_STATUS.get(str(err.get(key) or ""))
        if status:
            return status
    return 502


def error_in(data: dict | None, fmt: str) -> tuple[int, str] | None:
    """The provider's error in a stream event or a 200 body, as (status, message); None if it isn't one."""
    if not isinstance(data, dict):
        return None
    if fmt == "anthropic":
        if data.get("type") != "error":
            return None
        err = data.get("error") if isinstance(data.get("error"), dict) else {}
        return _status(err), str(err.get("message") or "upstream error")
    err = data.get("error")
    if err and not data.get("choices") and not data.get("data"):
        err = err if isinstance(err, dict) else {"message": str(err)}
        return _status(err), str(err.get("message") or "upstream error")
    choice = (data.get("choices") or [{}])[0] if isinstance(data.get("choices"), list) and data.get("choices") else {}
    if choice.get("finish_reason") == "error":  # OpenRouter: the upstream provider failed mid-request
        err = data.get("error") if isinstance(data.get("error"), dict) else {}
        return _status(err), str(err.get("message") or "upstream provider error")
    return None


def _started(ev: SSEEvent, fmt: str) -> bool:
    """Content (or the end) has arrived: from here on, the stream is the client's."""
    if ev.data.strip() == "[DONE]":
        return True
    d = ev.json() or {}
    if fmt == "anthropic":
        return d.get("type") in ("content_block_delta", "message_delta", "message_stop")
    choices = d.get("choices") or []
    if not choices:
        return bool(d.get("usage"))
    c = choices[0] or {}
    delta = c.get("delta") or {}
    return bool(c.get("finish_reason") or any(delta.get(k) for k in ("content", "tool_calls", "reasoning", "reasoning_content",
                                                                      "refusal", "function_call")))


def check_body(resp: UpstreamResponse, fmt: str, backend: str) -> None:
    found = error_in(resp.body, fmt)
    if found:
        status, message = found
        raise BackendError(status, f"{backend}: {message}", body=resp.body, retryable=status >= 500 or status in (408, 429))


async def start_stream(resp: UpstreamResponse, fmt: str, backend: str, first_event_timeout: float | None) -> UpstreamResponse:
    """Read a stream up to its first content. An error before then, or no event at all within
    ``first_event_timeout`` seconds, raises BackendError (after closing the upstream stream)."""
    assert resp.events is not None
    it = resp.events.__aiter__()
    buffered: list[SSEEvent] = []
    deadline = time.monotonic() + first_event_timeout if first_event_timeout else None
    try:
        while len(buffered) < _PEEK_LIMIT:
            try:
                if deadline is not None and not buffered:
                    ev = await asyncio.wait_for(it.__anext__(), max(0.001, deadline - time.monotonic()))
                else:
                    ev = await it.__anext__()
            except StopAsyncIteration:
                break
            buffered.append(ev)
            found = error_in(ev.json(), fmt)
            if found:
                status, message = found
                raise BackendError(status, f"{backend}: {message}", retryable=status >= 500 or status in (408, 429))
            if _started(ev, fmt):
                break
    except asyncio.TimeoutError:
        await resp.aclose()
        raise BackendError(504, f"{backend}: no response within {first_event_timeout:.0f}s", retryable=True)
    except httpx.HTTPError as e:
        await resp.aclose()
        raise BackendError(502, f"{backend}: stream broke before any content: {type(e).__name__}: {e}", retryable=True)
    except BackendError:
        await resp.aclose()
        raise

    async def replay():
        for ev in buffered:
            yield ev
        async for ev in it:
            yield ev

    resp.events = replay()
    return resp

7b129ebcc811d1b0:
"""Sending Chat Completions requests to a backend's Responses API (``/v1/responses``).

OpenAI's GPT-5.6 models reject function tools with reasoning on Chat Completions ("use /v1/responses or set
reasoning_effort to 'none'"), so an OpenAI backend with ``api: responses`` speaks the Responses API while the
rest of the gateway keeps seeing Chat Completions: requests are converted on the way out, and replies and
streams are converted back.

Stateless (``store: false``), like the rest of Merit Order. Reasoning items aren't carried between turns,
since the Chat Completions history the gateway holds has no place for them.
"""

from __future__ import annotations

from typing import Any

from .sse import SSEEvent, event

_PASS_THROUGH = ("temperature", "top_p", "parallel_tool_calls", "user", "prompt_cache_key", "safety_identifier",
                 "service_tier", "metadata")


def _text_of(content: Any) -> str:
    if isinstance(content, str):
        return content
    return "".join(p.get("text", "") for p in content or [] if isinstance(p, dict) and p.get("type") == "text")


def _user_content(content: Any) -> Any:
    if isinstance(content, str) or content is None:
        return content or ""
    parts = []
    for p in content:
        t = p.get("type")
        if t == "text":
            parts.append({"type": "input_text", "text": p.get("text", "")})
        elif t == "image_url":
            url = (p.get("image_url") or {}).get("url") if isinstance(p.get("image_url"), dict) else p.get("image_url")
            if url:
                parts.append({"type": "input_image", "image_url": url, "detail": (p.get("image_url") or {}).get("detail", "auto")
                              if isinstance(p.get("image_url"), dict) else "auto"})
    return parts


def chat_to_responses_request(body: dict) -> dict:
    items: list[dict] = []
    for m in body.get("messages") or []:
        role = m.get("role")
        if role in ("system", "developer"):
            items.append({"type": "message", "role": "developer", "content": _text_of(m.get("content"))})
        elif role == "user":
            items.append({"type": "message", "role": "user", "content": _user_content(m.get("content"))})
        elif role == "assistant":
            text = _text_of(m.get("content"))
            if text:
                items.append({"type": "message", "role": "assistant", "content": [{"type": "output_text", "text": text}]})
            for tc in m.get("tool_calls") or []:
                fn = tc.get("function") or {}
                items.append({"type": "function_call", "call_id": tc.get("id", ""), "name": fn.get("name", ""),
                              "arguments": fn.get("arguments") or "{}"})
        elif role == "tool":
            items.append({"type": "function_call_output", "call_id": m.get("tool_call_id", ""), "output": _text_of(m.get("content"))})

    out: dict[str, Any] = {"model": body.get("model"), "input": items, "store": False}
    limit = body.get("max_completion_tokens") or body.get("max_tokens")
    if limit:
        out["max_output_tokens"] = limit
    for k in _PASS_THROUGH:
        if body.get(k) is not None:
            out[k] = body[k]
    if body.get("reasoning_effort"):
        out["reasoning"] = {"effort": body["reasoning_effort"]}
    tools = []
    for t in body.get("tools") or []:
        if t.get("type") != "function":
            continue
        fn = t.get("function") or {}
        # Responses makes function tools strict unless told otherwise; most clients' schemas aren't strict-ready.
        tools.append({"type": "function", "name": fn.get("name", ""), "description": fn.get("description"),
                      "parameters": fn.get("parameters") or {"type": "object", "properties": {}}, "strict": bool(fn.get("strict", False))})
    if tools:
        out["tools"] = [{k: v for k, v in t.items() if v is not None} for t in tools]
        tc = body.get("tool_choice")
        if isinstance(tc, str):
            out["tool_choice"] = tc
        elif isinstance(tc, dict) and tc.get("type") == "function":
            out["tool_choice"] = {"type": "function", "name": (tc.get("function") or {}).get("name")}
    rf = body.get("response_format") or {}
    if rf.get("type") == "json_schema":
        js = rf.get("json_schema") or {}
        out["text"] = {"format": {"type": "json_schema", "name": js.get("name", "output"), "schema": js.get("schema") or {},
                                  "strict": bool(js.get("strict", False))}}
    elif rf.get("type") == "json_object":
        out["text"] = {"format": {"type": "json_object"}}
    if body.get("stream"):
        out["stream"] = True
    return out


def chat_usage(u: dict | None) -> dict | None:
    if not u:
        return None
    prompt, completion = u.get("input_tokens") or 0, u.get("output_tokens") or 0
    return {"prompt_tokens": prompt, "completion_tokens": completion, "total_tokens": u.get("total_tokens") or prompt + completion,
            "prompt_tokens_details": {"cached_tokens": (u.get("input_tokens_details") or {}).get("cached_tokens") or 0},
            "completion_tokens_details": {"reasoning_tokens": (u.get("output_tokens_details") or {}).get("reasoning_tokens") or 0}}


def _finish(resp: dict, has_calls: bool) -> str:
    if has_calls:
        return "tool_calls"
    if resp.get("status") == "incomplete":
        reason = (resp.get("incomplete_details") or {}).get("reason")
        return "content_filter" if reason == "content_filter" else "length"
    return "stop"


def responses_to_chat_completion(resp: dict) -> dict:
    text, refusal, calls = "", "", []
    for item in resp.get("output") or []:
        if item.get("type") == "message":
            for part in item.get("content") or []:
                if part.get("type") == "output_text":
                    text += part.get("text", "")
                elif part.get("type") == "refusal":
                    refusal += part.get("refusal", "")
        elif item.get("type") == "function_call":
            calls.append({"id": item.get("call_id") or item.get("id"), "type": "function",
                          "function": {"name": item.get("name", ""), "arguments": item.get("arguments") or "{}"}})
    msg: dict[str, Any] = {"role": "assistant", "content": text or None}
    if refusal:
        msg["refusal"] = refusal
    if calls:
        msg["tool_calls"] = calls
    out = {"id": resp.get("id", ""), "object": "chat.completion", "created": resp.get("created_at") or 0,
           "model": resp.get("model", ""), "choices": [{"index": 0, "message": msg, "finish_reason": _finish(resp, bool(calls))}]}
    usage = chat_usage(resp.get("usage"))
    if usage:
        out["usage"] = usage
    return out


class ResponsesToChatStream:
    """Turns Responses API stream events into Chat Completions chunks, ending with a usage chunk and [DONE]."""

    def __init__(self) -> None:
        self.id, self.model, self.created = "", "", 0
        self.calls: dict[str, int] = {}  # function_call item id -> chat tool index
        self.done = False

    def _chunk(self, delta: dict | None = None, finish: str | None = None, usage: dict | None = None) -> SSEEvent:
        d: dict[str, Any] = {"id": self.id, "object": "chat.completion.chunk", "created": self.created, "model": self.model,
                             "choices": [] if delta is None else [{"index": 0, "delta": delta, "finish_reason": finish}]}
        if usage is not None:
            d["usage"] = usage
        return event(d)

    def feed(self, ev: SSEEvent) -> list[SSEEvent]:
        if self.done:
            return []
        d = ev.json()
        if not d:
            return []
        t = d.get("type") or ev.event
        if t == "response.created":
            r = d.get("response") or {}
            self.id, self.model, self.created = r.get("id", ""), r.get("model", ""), r.get("created_at") or 0
            return [self._chunk({"role": "assistant", "content": ""})]
        if t == "response.output_text.delta":
            return [self._chunk({"content": d.get("delta", "")})]
        if t == "response.refusal.delta":
            return [self._chunk({"refusal": d.get("delta", "")})]
        if t == "response.output_item.added" and (d.get("item") or {}).get("type") == "function_call":
            item = d["item"]
            i = self.calls.setdefault(item.get("id") or str(d.get("output_index")), len(self.calls))
            return [self._chunk({"tool_calls": [{"index": i, "id": item.get("call_id") or item.get("id"), "type": "function",
                                                 "function": {"name": item.get("name", ""), "arguments": item.get("arguments") or ""}}]})]
        if t == "response.function_call_arguments.delta":
            i = self.calls.get(d.get("item_id") or str(d.get("output_index")))
            if i is None:
                return []
            return [self._chunk({"tool_calls": [{"index": i, "function": {"arguments": d.get("delta", "")}}]})]
        if t in ("response.completed", "response.incomplete"):
            self.done = True
            r = d.get("response") or {}
            usage = chat_usage(r.get("usage"))
            out = [self._chunk({}, _finish(r, bool(self.calls)))]
            if usage:
                out.append(self._chunk(None, usage=usage))
            return out + [SSEEvent(data="[DONE]")]
        if t in ("response.failed", "error"):
            self.done = True
            err = (d.get("response") or {}).get("error") or d.get("error") or d
            err = err if isinstance(err, dict) else {"message": str(err)}
            out_err = {"message": err.get("message") or "upstream error", "type": "api_error"}
            if err.get("code"):  # e.g. rate_limit_exceeded: lets the gateway treat it as busy rather than broken
                out_err["code"] = err["code"]
            return [event({"error": out_err}), SSEEvent(data="[DONE]")]
        return []


async def to_chat_stream(events):
    conv = ResponsesToChatStream()
    async for ev in events:
        for out in conv.feed(ev):
            yield out
    if not conv.done:
        yield SSEEvent(data="[DONE]")

