"""OpenAI Responses API (``/v1/responses``) on top of the Chat Completions pipeline.

Requests are converted to Chat Completions, routed like any other request (to
OpenAI-format or Anthropic-format backends), and the result is converted back.

Stateless only: Merit Order doesn't store conversations, so ``previous_response_id``
is rejected and clients send the full input each turn (what Codex CLI and
``store: false`` clients do). Reasoning items from earlier turns are dropped.
"""

from __future__ import annotations

import json
import time
import uuid
from typing import Any

from ..pricing import Usage
from .sse import SSEEvent, event
from .translate import EFFORTS, usage_from_openai


class ResponsesError(Exception):
    pass


def _id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex[:24]}"


def _content_to_chat(content: Any) -> Any:
    if isinstance(content, str):
        return content
    parts = []
    for p in content or []:
        t = p.get("type")
        if t in ("input_text", "output_text", "text"):
            parts.append({"type": "text", "text": p.get("text", "")})
        elif t == "input_image":
            url = p.get("image_url") or (p.get("file_id") and f"file:{p['file_id']}")
            if url:
                parts.append({"type": "image_url", "image_url": {"url": url}})
    if parts and all(p["type"] == "text" for p in parts):
        return "".join(p["text"] for p in parts)
    return parts


def responses_to_chat(body: dict) -> dict:
    if body.get("previous_response_id"):
        raise ResponsesError("previous_response_id isn't supported: Merit Order doesn't store conversations. "
                             "Send the full conversation in `input` (store: false).")
    messages: list[dict] = []
    if body.get("instructions"):
        messages.append({"role": "system", "content": body["instructions"]})
    items = body.get("input")
    if isinstance(items, str):
        items = [{"role": "user", "content": items}]
    pending_calls: list[dict] = []

    def flush_calls() -> None:
        if pending_calls:
            messages.append({"role": "assistant", "content": None, "tool_calls": list(pending_calls)})
            pending_calls.clear()

    for item in items or []:
        t = item.get("type", "message")
        if t == "message" or ("role" in item and t not in ("function_call", "function_call_output")):
            flush_calls()
            role = item.get("role", "user")
            role = "system" if role == "developer" else role
            messages.append({"role": role, "content": _content_to_chat(item.get("content"))})
        elif t == "function_call":
            pending_calls.append({"id": item.get("call_id") or item.get("id"), "type": "function",
                                  "function": {"name": item.get("name", ""), "arguments": item.get("arguments") or "{}"}})
        elif t == "function_call_output":
            flush_calls()
            output = item.get("output")
            messages.append({"role": "tool", "tool_call_id": item.get("call_id", ""),
                             "content": output if isinstance(output, str) else json.dumps(output)})
        # reasoning, web_search_call, etc.: no Chat Completions equivalent; dropped
    flush_calls()

    out: dict[str, Any] = {"model": body.get("model"), "messages": messages}
    if body.get("max_output_tokens"):
        out["max_tokens"] = body["max_output_tokens"]
    for k in ("temperature", "top_p", "parallel_tool_calls", "user", "prompt_cache_key"):
        if body.get(k) is not None:
            out[k] = body[k]
    effort = (body.get("reasoning") or {}).get("effort")
    if effort in EFFORTS:
        out["reasoning_effort"] = effort
    tools = [
        {"type": "function", "function": {k: v for k, v in (("name", t.get("name")), ("description", t.get("description")),
                                                          ("parameters", t.get("parameters")), ("strict", t.get("strict"))) if v is not None}}
        for t in body.get("tools") or [] if t.get("type") == "function"
    ]
    if tools:
        out["tools"] = tools
        tc = body.get("tool_choice")
        if isinstance(tc, str):
            out["tool_choice"] = tc
        elif isinstance(tc, dict) and tc.get("type") == "function":
            out["tool_choice"] = {"type": "function", "function": {"name": tc.get("name")}}
    fmt = (body.get("text") or {}).get("format") or {}
    if fmt.get("type") == "json_schema":
        out["response_format"] = {"type": "json_schema", "json_schema": {"name": fmt.get("name", "output"), "schema": fmt.get("schema"),
                                                                          "strict": fmt.get("strict", False)}}
    if body.get("stream"):
        out["stream"] = True
        out["stream_options"] = {"include_usage": True}
    return out


def responses_usage(u: Usage) -> dict:
    return {
        "input_tokens": u.prompt_tokens,
        "input_tokens_details": {"cached_tokens": u.cache_read_tokens},
        "output_tokens": u.output_tokens,
        "output_tokens_details": {"reasoning_tokens": 0},
        "total_tokens": u.total_tokens,
    }


def _response_obj(rid: str, model: str, created: int, status: str, output: list, usage: dict | None) -> dict:
    return {"id": rid, "object": "response", "created_at": created, "status": status, "model": model, "output": output,
            "usage": usage, "error": None, "incomplete_details": None, "parallel_tool_calls": True, "tool_choice": "auto",
            "tools": [], "store": False}


def chat_to_responses(resp: dict, model: str) -> dict:
    choice = (resp.get("choices") or [{}])[0]
    msg = choice.get("message") or {}
    output: list[dict] = []
    if msg.get("content"):
        output.append({"type": "message", "id": _id("msg"), "status": "completed", "role": "assistant",
                       "content": [{"type": "output_text", "text": msg["content"], "annotations": []}]})
    for tc in msg.get("tool_calls") or []:
        fn = tc.get("function") or {}
        output.append({"type": "function_call", "id": _id("fc"), "call_id": tc.get("id") or _id("call"), "name": fn.get("name", ""),
                       "arguments": fn.get("arguments") or "{}", "status": "completed"})
    status = "incomplete" if choice.get("finish_reason") == "length" else "completed"
    obj = _response_obj(_id("resp"), model, int(time.time()), status, output, responses_usage(usage_from_openai(resp.get("usage"))))
    if status == "incomplete":
        obj["incomplete_details"] = {"reason": "max_output_tokens"}
    return obj


class ChatToResponsesStream:
    """Converts Chat Completions chunks into Responses API streaming events."""

    def __init__(self, model: str):
        self.rid = _id("resp")
        self.model = model
        self.created = int(time.time())
        self.seq = 0
        self.started = False
        self.output: list[dict] = []
        self.msg: dict | None = None  # open message item
        self.calls: dict[int, dict] = {}  # chat tool index -> function_call item
        self.usage = Usage()
        self.finish: str | None = None
        self.done = False

    def _ev(self, type_: str, **data) -> SSEEvent:
        self.seq += 1
        return event({"type": type_, "sequence_number": self.seq, **data}, type_)

    def _start(self) -> list[SSEEvent]:
        self.started = True
        obj = _response_obj(self.rid, self.model, self.created, "in_progress", [], None)
        return [self._ev("response.created", response=obj), self._ev("response.in_progress", response=obj)]

    def _close_msg(self) -> list[SSEEvent]:
        if not self.msg:
            return []
        m, self.msg = self.msg, None
        idx = self.output.index(m)
        text = m["content"][0]["text"]
        m["status"] = "completed"
        return [
            self._ev("response.output_text.done", item_id=m["id"], output_index=idx, content_index=0, text=text),
            self._ev("response.content_part.done", item_id=m["id"], output_index=idx, content_index=0, part=m["content"][0]),
            self._ev("response.output_item.done", output_index=idx, item=m),
        ]

    def feed(self, ev: SSEEvent) -> list[SSEEvent]:
        if ev.data.strip() == "[DONE]":
            return self.finish_events()
        d = ev.json()
        if not d:
            return []
        out = [] if self.started else self._start()
        if d.get("error"):
            err = d["error"] if isinstance(d["error"], dict) else {"message": str(d["error"])}
            out.append(self._ev("error", code=err.get("type", "api_error"), message=err.get("message", "upstream error"), param=None))
            return out
        if d.get("usage"):
            self.usage.merge(usage_from_openai(d["usage"]))
        for ch in d.get("choices") or []:
            delta = ch.get("delta") or {}
            if delta.get("content"):
                if self.msg is None:
                    self.msg = {"type": "message", "id": _id("msg"), "status": "in_progress", "role": "assistant",
                                "content": [{"type": "output_text", "text": "", "annotations": []}]}
                    self.output.append(self.msg)
                    idx = len(self.output) - 1
                    out.append(self._ev("response.output_item.added", output_index=idx,
                                        item={**self.msg, "content": []}))
                    out.append(self._ev("response.content_part.added", item_id=self.msg["id"], output_index=idx, content_index=0,
                                        part={"type": "output_text", "text": "", "annotations": []}))
                self.msg["content"][0]["text"] += delta["content"]
                out.append(self._ev("response.output_text.delta", item_id=self.msg["id"], output_index=self.output.index(self.msg),
                                    content_index=0, delta=delta["content"]))
            for tc in delta.get("tool_calls") or []:
                i = tc.get("index", 0)
                fn = tc.get("function") or {}
                if i not in self.calls:
                    out += self._close_msg()
                    item = {"type": "function_call", "id": _id("fc"), "call_id": tc.get("id") or _id("call"),
                            "name": fn.get("name", ""), "arguments": "", "status": "in_progress"}
                    self.calls[i] = item
                    self.output.append(item)
                    out.append(self._ev("response.output_item.added", output_index=len(self.output) - 1, item=dict(item)))
                item = self.calls[i]
                if fn.get("arguments"):
                    item["arguments"] += fn["arguments"]
                    out.append(self._ev("response.function_call_arguments.delta", item_id=item["id"],
                                        output_index=self.output.index(item), delta=fn["arguments"]))
            if ch.get("finish_reason"):
                self.finish = ch["finish_reason"]
        return out

    def finish_events(self) -> list[SSEEvent]:
        if self.done:
            return []
        self.done = True
        out = [] if self.started else self._start()
        out += self._close_msg()
        for item in self.calls.values():
            idx = self.output.index(item)
            item["status"] = "completed"
            out.append(self._ev("response.function_call_arguments.done", item_id=item["id"], output_index=idx, arguments=item["arguments"]))
            out.append(self._ev("response.output_item.done", output_index=idx, item=item))
        status = "incomplete" if self.finish == "length" else "completed"
        obj = _response_obj(self.rid, self.model, self.created, status, self.output, responses_usage(self.usage))
        if status == "incomplete":
            obj["incomplete_details"] = {"reason": "max_output_tokens"}
        out.append(self._ev("response.completed" if status == "completed" else "response.incomplete", response=obj))
        return out

