"""Reference solution for c5-lisp: a small Scheme-like interpreter with closures and proper tail calls."""

import sys
from fractions import Fraction


class LispError(Exception):
    pass


class Symbol(str):
    __slots__ = ()


_SYMBOLS = {}


def sym(name):
    s = _SYMBOLS.get(name)
    if s is None:
        s = _SYMBOLS[name] = Symbol(name)
    return s


class LStr:
    __slots__ = ("s",)

    def __init__(self, s):
        self.s = s


class Pair:
    __slots__ = ("car", "cdr", "_items")

    def __init__(self, car, cdr):
        self.car, self.cdr, self._items = car, cdr, None


class _Nil:
    __slots__ = ()


class _Void:
    __slots__ = ()


NIL = _Nil()
VOID = _Void()
UNASSIGNED = object()


class Closure:
    __slots__ = ("params", "rest", "body", "env")

    def __init__(self, params, rest, body, env):
        self.params, self.rest, self.body, self.env = params, rest, body, env


class Builtin:
    __slots__ = ("name", "fn", "lo", "hi")

    def __init__(self, name, fn, lo, hi):
        self.name, self.fn, self.lo, self.hi = name, fn, lo, hi


class Env:
    __slots__ = ("vars", "parent")

    def __init__(self, vars, parent):
        self.vars, self.parent = vars, parent

    def lookup(self, s):
        e = self
        while e is not None:
            v = e.vars.get(s, e)
            if v is not e:
                if v is UNASSIGNED:
                    raise LispError(f"variable used before its letrec init: {s}")
                return v
            e = e.parent
        raise LispError(f"unbound symbol: {s}")

    def frame_of(self, s):
        e = self
        while e is not None:
            if s in e.vars:
                return e
            e = e.parent
        raise LispError(f"set! of an unbound symbol: {s}")


# ---------------------------------------------------------------- reader

_DELIMS = set("()'\";") | set(" \t\n\r")
_ESC = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}
_DOT = object()
_LP, _RP, _QT = object(), object(), object()
_PUNCT = {"(": _LP, ")": _RP, "'": _QT}


def tokenize(src):
    toks, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c in " \t\n\r":
            i += 1
        elif c == ";":
            while i < n and src[i] != "\n":
                i += 1
        elif c in "()'":
            toks.append(_PUNCT[c])
            i += 1
        elif c == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise LispError("unterminated string")
                c = src[i]
                if c == '"':
                    i += 1
                    break
                if c == "\\":
                    if i + 1 >= n:
                        raise LispError("unterminated string")
                    e = src[i + 1]
                    if e not in _ESC:
                        raise LispError(f"bad string escape \\{e}")
                    buf.append(_ESC[e])
                    i += 2
                else:
                    buf.append(c)
                    i += 1
            toks.append(LStr("".join(buf)))
        else:
            j = i
            while j < n and src[j] not in _DELIMS:
                j += 1
            toks.append(_atom(src[i:j]))
            i = j
    return toks


def _atom(t):
    body = t[1:] if t[0] in "+-" else t
    if body and all("0" <= ch <= "9" for ch in body):
        return int(t)
    if t == "#t":
        return True
    if t == "#f":
        return False
    if t.startswith("#"):
        raise LispError(f"bad token {t}")
    if t == ".":
        return _DOT
    return sym(t)


def read_all(src):
    toks = tokenize(src)
    pos = 0
    out = []

    def read():
        nonlocal pos
        if pos >= len(toks):
            raise LispError("unexpected end of input")
        t = toks[pos]
        pos += 1
        if t is _LP:
            items, tail = [], NIL
            while True:
                if pos >= len(toks):
                    raise LispError("missing )")
                t = toks[pos]
                if t is _RP:
                    pos += 1
                    break
                if t is _DOT:
                    if not items:
                        raise LispError("bad dotted list")
                    pos += 1
                    tail = read()
                    if pos >= len(toks) or toks[pos] is not _RP:
                        raise LispError("bad dotted list")
                    pos += 1
                    break
                items.append(read())
            for item in reversed(items):
                tail = Pair(item, tail)
            return tail
        if t is _RP:
            raise LispError("unexpected )")
        if t is _QT:
            return Pair(sym("quote"), Pair(read(), NIL))
        if t is _DOT:
            raise LispError("unexpected .")
        return t

    while pos < len(toks):
        out.append(read())
    return out


# ---------------------------------------------------------------- values

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def is_num(x):
    return is_int(x) or type(x) is Fraction


def norm(x):
    if type(x) is Fraction and x.denominator == 1:
        return x.numerator
    return x


def items_of(x, what="list"):
    """Elements of a proper list as a tuple (cached on source pairs, which never change)."""
    if x is NIL:
        return ()
    if type(x) is not Pair:
        raise LispError(f"not a proper {what}")
    if x._items is not None:
        return x._items
    out, p = [], x
    while type(p) is Pair:
        out.append(p.car)
        p = p.cdr
    if p is not NIL:
        raise LispError(f"not a proper {what}")
    x._items = tuple(out)
    return x._items


def is_list(x):
    while type(x) is Pair:
        x = x.cdr
    return x is NIL


def make_list(xs, tail=NIL):
    for x in reversed(xs):
        tail = Pair(x, tail)
    return tail


def to_str(x):
    if x is True:
        return "#t"
    if x is False:
        return "#f"
    if is_int(x):
        return str(x)
    if type(x) is Fraction:
        return f"{x.numerator}/{x.denominator}"
    if type(x) is Symbol:
        return str(x)
    if type(x) is LStr:
        s = x.s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\t", "\\t")
        return f'"{s}"'
    if x is NIL:
        return "()"
    if x is VOID:
        return "#<void>"
    if type(x) is Pair:
        parts = []
        while type(x) is Pair:
            parts.append(to_str(x.car))
            x = x.cdr
        if x is not NIL:
            parts.append(".")
            parts.append(to_str(x))
        return "(" + " ".join(parts) + ")"
