def eqp(a, b):
    if is_num(a) and is_num(b):
        return a == b
    if isinstance(a, bool) or isinstance(b, bool):
        return a is b
    if type(a) is Symbol and type(b) is Symbol:
        return a == b
    return a is b


def equalp(a, b):
    while type(a) is Pair and type(b) is Pair:
        if not equalp(a.car, b.car):
            return False
        a, b = a.cdr, b.cdr
    if type(a) is LStr and type(b) is LStr:
        return a.s == b.s
    return eqp(a, b)


# ---------------------------------------------------------------- builtins

def _nums(name, args):
    for a in args:
        if not is_num(a):
            raise LispError(f"{name}: not a number: {to_str(a)}")
    return args


def _ints(name, args):
    for a in args:
        if not is_int(a):
            raise LispError(f"{name}: not an integer: {to_str(a)}")
    return args


def b_add(args):
    t = 0
    for a in _nums("+", args):
        t += a
    return norm(t)


def b_mul(args):
    t = 1
    for a in _nums("*", args):
        t *= a
    return norm(t)


def b_sub(args):
    _nums("-", args)
    if len(args) == 1:
        return -args[0]
    t = args[0]
    for a in args[1:]:
        t -= a
    return norm(t)


def b_div(args):
