    return _quot(a, b)


def b_remainder(args):
    a, b = _ints("remainder", args)
    if b == 0:
        raise LispError("division by zero")
    return a - b * _quot(a, b)


def b_modulo(args):
    a, b = _ints("modulo", args)
    if b == 0:
