BUILTINS = {
    "+": (b_add, 0, None), "*": (b_mul, 0, None), "-": (b_sub, 1, None), "/": (b_div, 1, None),
    "quotient": (b_quotient, 2, 2), "remainder": (b_remainder, 2, 2), "modulo": (b_modulo, 2, 2),
    "abs": (b_abs, 1, 1),
