                for e in form[2:-1]:
                    ev(e, env)
                x = form[-1]
                continue
            if op is S_COND:
                chosen = None
                for clause in form[1:]:
                    parts = items_of(clause, "cond clause")
                    if not parts:
                        raise LispError("empty cond clause")
                    if parts[0] is S_ELSE:
                        if len(parts) < 2:
                            raise LispError("empty else clause")
                        chosen = parts[1:]
                        break
                    v = ev(parts[0], env)
                    if v is not False:
                        if len(parts) == 1:
                            return v
                        chosen = parts[1:]
                        break
                if chosen is None:
                    return VOID
                for e in chosen[:-1]:
                    ev(e, env)
                x = chosen[-1]
                continue
            if op is S_AND or op is S_OR:
                if n == 1:
                    return op is S_AND
                stop = False
                for e in form[1:-1]:
                    v = ev(e, env)
                    if (v is False) if op is S_AND else (v is not False):
                        stop = True
                        break
                if stop:
                    return v
                x = form[-1]
                continue
        f = ev(op, env)
        args = [ev(a, env) for a in form[1:]]
        tf = type(f)
        if tf is Builtin:
            return call_builtin(f, args)
        if tf is not Closure:
            raise LispError(f"not a procedure: {to_str(f)}")
        env = bind(f, args)
        body = f.body
        for e in body[:-1]:
            ev(e, env)
        x = body[-1]


def global_env():
    return Env({sym(name): Builtin(name, fn, lo, hi) for name, (fn, lo, hi) in BUILTINS.items()}, None)


def run(source):
    forms = read_all(source)
    env = global_env()
    old = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old, 20000))
    try:
        value = VOID
        for form in forms:
            value = ev(form, env)
        return to_str(value)
    except RecursionError:
        raise LispError("recursion too deep") from None
    finally:
        sys.setrecursionlimit(old)

