"""Session identity, prefix hashing, and task-boundary detection.

The gateway keeps only metadata about a session (hashes, timestamps, which
backend holds its cache). Conversation content is never stored.
"""

from __future__ import annotations

import hashlib
import json
import re
from dataclasses import asdict, dataclass, field
from typing import Any

_CLAUDE_CODE_SESSION = re.compile(r"session_([0-9a-fA-F-]{8,})")


def _canon(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str).encode()


def est_tokens(value: Any) -> int:
    """Rough token estimate (~4 characters per token). Good enough for routing."""
    return max(1, len(_canon(value)) // 4)


def _first_user_text(body: dict) -> str:
    for m in body.get("messages") or []:
        if m.get("role") == "user":
            c = m.get("content")
            if isinstance(c, str):
                return c[:2000]
            return _canon(c)[:2000].decode(errors="replace")
    return ""


def session_key(user_id: str, sid: str) -> str:
    """Where a session's routing state and spend live. Scoped to the user, so another caller sending the
    same session id can't read or change it (or use up its spend cap). Length-prefixed: no collisions."""
    return f"{len(user_id)}:{user_id}:{sid}"


def session_id(headers: dict[str, str], body: dict, fmt: str, user_id: str) -> tuple[str, str]:
    """Returns (session_id, source)."""
    for h in ("x-session-id", "x-meritorder-session", "x-claude-code-session-id"):
        if headers.get(h):
            return headers[h][:128], "header"
    meta_user = str((body.get("metadata") or {}).get("user_id") or "")
    m = _CLAUDE_CODE_SESSION.search(meta_user)
    if m:
        return m.group(1), "metadata"
    system = body.get("system") if fmt == "anthropic" else [
        x.get("content") for x in body.get("messages") or [] if x.get("role") in ("system", "developer")
    ]
    digest = hashlib.sha256(_canon([user_id, system, _first_user_text(body)])).hexdigest()[:24]
    return f"fp-{digest}", "fingerprint"


def thread_suffix(headers: dict[str, str]) -> str:
    """Which conversation inside a session a request belongs to, for routing state.

    Claude Code sends its subagents' turns and its side requests (titles, summaries, permission checks) under the
    main session's id. Each is a separate conversation with its own history and cache, so each keeps its own model,
    level and cache state; otherwise every subagent turn would reset the main conversation's. Spend limits and the
    ledger still count the whole session.
    """
    suffix = ""
    agent = headers.get("x-claude-code-agent-id")
    if agent:
        suffix += f"/agent:{agent[:64]}"
    if (headers.get("x-claude-code-request-class") or "").lower() == "auxiliary":
        suffix += "/aux"
    return suffix


def _messages(body: dict) -> list:
    return body.get("messages") or []


def prefix_hash(body: dict, upto: int) -> str:
    """Hash of everything that forms the cacheable prefix up to message ``upto``.

    One serialization call for the whole prefix: per-message calls cost milliseconds on long agent sessions.
    """
    return hashlib.sha256(_canon([body.get("tools"), body.get("system"), _messages(body)[:upto]])).hexdigest()


def is_task_boundary(body: dict) -> bool:
    """A new human prompt starts a task; tool results continue one."""
    msgs = _messages(body)
    if not msgs:
        return True
    last = msgs[-1]
    if last.get("role") == "tool":
        return False
    if last.get("role") != "user":
        return False
    content = last.get("content")
    if isinstance(content, list) and any(isinstance(b, dict) and b.get("type") == "tool_result" for b in content):
        return False
    return True


@dataclass
class Session:
    id: str
    model: str | None = None
    backend: str | None = None
    floor: str | None = None
    turns: int = 0
    last_seen: float = 0.0
    msg_count: int = 0
    prefix_hash: str | None = None
    prefix_tokens: int = 0
    warm_until: dict[str, float] = field(default_factory=dict)
    effort: str | None = None  # chosen once per session: changing it would invalidate the prompt cache
    thread: str | None = None  # where this conversation's routing state lives (see thread_suffix); None = the session

    @property
    def state_id(self) -> str:
        return self.thread or self.id

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict | None, sid: str, thread: str | None = None) -> "Session":
        thread = thread if thread and thread != sid else None
        if not d:
            return cls(id=sid, thread=thread)
        known = {k: v for k, v in d.items() if k in cls.__dataclass_fields__}
        known["id"], known["thread"] = sid, thread
        return cls(**known)

    def compacted(self, body: dict) -> bool:
        """True when the harness rewrote history (so every cache for it is dead)."""
        if not self.prefix_hash or not self.msg_count:
            return False
        if len(_messages(body)) < self.msg_count:
            return True
        return prefix_hash(body, self.msg_count) != self.prefix_hash

    def warm(self, backend: str, now: float) -> bool:
        return self.warm_until.get(backend, 0.0) > now

d68491fc5a26ee44:
"""Eval runner: measure each model's quality on mechanically graded tasks.

Results turn into suggested quality scores (the 1-5 numbers `auto` routing uses):
a model's score for a task type is the highest level L such that it passes at least
`threshold` of the tasks at every level up to L.
"""

from __future__ import annotations

import asyncio
import json
import re
import time
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import httpx
import yaml

STARTER = Path(__file__).with_name("starter.yaml")
_NUMBER = re.compile(r"-?\d+(?:[.,]\d+)?")
_FENCE = re.compile(r"^```[a-zA-Z]*\s*|\s*```$")


def load_suite(path: str | Path | None = None) -> dict:
    data = yaml.safe_load(Path(path or STARTER).read_text())
    tasks = data.get("tasks") or []
    for t in tasks:
        if not {"id", "task", "level", "prompt", "checks"} <= set(t):
            raise ValueError(f"task {t.get('id', '?')} needs id, task, level, prompt, and checks")
    return {"name": data.get("name") or Path(path or STARTER).stem, "tasks": tasks}


def _text(reply: dict) -> str:
    msg = ((reply.get("choices") or [{}])[0].get("message") or {})
    return (msg.get("content") or "").strip()


def _tool_calls(reply: dict) -> list[dict]:
    msg = ((reply.get("choices") or [{}])[0].get("message") or {})
    return msg.get("tool_calls") or []


def _unfence(s: str) -> str:
    return _FENCE.sub("", s.strip()).strip()


def grade(check: dict, reply: dict) -> tuple[bool, str]:
    """Returns (passed, why) for one check against an OpenAI-format chat completion."""
    text = _text(reply)
    kind, expected = next(iter(check.items()))
    if kind == "contains":
        return str(expected).lower() in text.lower(), f"expected to contain {expected!r}"
    if kind == "not_contains":
        return str(expected).lower() not in text.lower(), f"expected not to contain {expected!r}"
    if kind == "equals":
        return _unfence(text).rstrip(".").strip() == str(expected), f"expected exactly {expected!r}"
    if kind == "regex":
        return re.search(expected, text, re.IGNORECASE | re.MULTILINE) is not None, f"expected to match /{expected}/"
    if kind == "number":
        nums = _NUMBER.findall(text.replace(",", ""))
        if not nums:
            return False, "no number in the reply"
        tol = check.get("tolerance", 1e-6) if isinstance(check, dict) else 1e-6
        return abs(float(nums[-1]) - float(expected)) <= tol, f"expected {expected}, got {nums[-1]}"
    if kind == "json":
        try:
            value = json.loads(_unfence(text))
        except json.JSONDecodeError:
            return False, "reply isn't valid JSON"
        if not isinstance(value, dict):
            return False, "reply isn't a JSON object"
        missing = {k: v for k, v in (expected or {}).items() if value.get(k) != v}
        return not missing, f"wrong or missing keys: {missing}" if missing else ""
    if kind == "tool_call":
        for call in _tool_calls(reply):
            fn = call.get("function") or {}
            if fn.get("name") != expected.get("name"):
                continue
            try:
                args = json.loads(fn.get("arguments") or "{}")
            except json.JSONDecodeError:
                return False, "tool arguments aren't valid JSON"
            want = expected.get("arguments") or {}
            if all(str(args.get(k, "")).strip().lower() == str(v).lower() for k, v in want.items()):
                return True, ""
            return False, f"called {fn.get('name')} with {args}, expected {want}"
        return False, f"expected a call to {expected.get('name')}"
    if kind == "regex_behaves":
        pattern = _unfence(text).strip().strip("/")
        if len(pattern) > 500:
            return False, "regex too long"
        try:
            rx = re.compile(pattern)
        except re.error as e:
            return False, f"not a valid regex: {e}"
        bad = [s for s in expected.get("match", []) if not rx.fullmatch(s)] + [s for s in expected.get("reject", []) if rx.fullmatch(s)]
        return not bad, f"wrong on {bad}" if bad else ""
    return False, f"unknown check {kind}"


@dataclass
class TaskResult:
    model: str
    task_id: str
    task: str
    level: int
    passed: bool
    reasons: list[str] = field(default_factory=list)
    cost: float = 0.0
    latency_ms: int = 0
    error: str | None = None


async def run_task(client: httpx.AsyncClient, gateway: str, key: str, model: str, t: dict, tag: str) -> TaskResult:
    body: dict[str, Any] = {"model": model, "messages": [{"role": "user", "content": t["prompt"]}], "max_tokens": t.get("max_tokens", 2000)}
    if t.get("tools"):
        body["tools"] = t["tools"]
    headers = {"authorization": f"Bearer {key}", "x-session-id": f"eval-{uuid.uuid4().hex[:12]}", "x-meritorder-cache": "off",
               "x-meritorder-tags": f"eval={tag}"}
    t0 = time.monotonic()
    result = TaskResult(model=model, task_id=t["id"], task=t["task"], level=int(t["level"]), passed=False)
    try:
        r = await client.post(f"{gateway}/v1/chat/completions", json=body, headers=headers)
        result.latency_ms = int((time.monotonic() - t0) * 1000)
        result.cost = float(r.headers.get("x-meritorder-cost-usd") or 0)
        if r.status_code != 200:
            result.error = f"HTTP {r.status_code}: {r.text[:200]}"
            return result
        reply = r.json()
        outcomes = [grade(c, reply) for c in t["checks"]]
        result.passed = all(ok for ok, _ in outcomes)
        result.reasons = [why for ok, why in outcomes if not ok]
    except httpx.HTTPError as e:
        result.error = f"{type(e).__name__}: {e}"
    return result


async def run_suite(gateway: str, key: str, models: list[str], suite: dict, concurrency: int = 4, repeat: int = 1,
                    progress=None, client: httpx.AsyncClient | None = None) -> list[TaskResult]:
    tag = f"{suite['name']}-{time.strftime('%Y%m%d%H%M')}"
    sem = asyncio.Semaphore(concurrency)
    own = client is None
    http = client or httpx.AsyncClient(timeout=300)

    async def one(model, t):
        async with sem:
            res = await run_task(http, gateway.rstrip("/"), key, model, t, tag)
            if progress:
                progress(res)
            return res

    try:
        return list(await asyncio.gather(*[one(m, t) for m in models for t in suite["tasks"] for _ in range(repeat)]))
    finally:
        if own:
            await http.aclose()


def score(results: list[TaskResult], threshold: float = 0.75) -> dict[str, dict]:
    """Per model: pass rates by task type and level, suggested quality per task type, cost and latency."""
    out: dict[str, dict] = {}
    for model in sorted({r.model for r in results}):
        mine = [r for r in results if r.model == model]
        by_task: dict[str, dict] = {}
        for task in sorted({r.task for r in mine}):
            levels = {}
            for lvl in sorted({r.level for r in mine if r.task == task}):
                rs = [r for r in mine if r.task == task and r.level == lvl]
                levels[lvl] = sum(r.passed for r in rs) / len(rs)
            suggested = 0
            for lvl in range(1, 6):
                if lvl in levels and levels[lvl] < threshold:
                    break
                if lvl in levels:
                    suggested = lvl
            by_task[task] = {"levels": levels, "suggested": max(suggested, 1) if any(levels.values()) else 0,
                             "pass_rate": sum(r.passed for r in mine if r.task == task) / max(1, len([r for r in mine if r.task == task]))}
        out[model] = {
            "tasks": by_task,
            "pass_rate": sum(r.passed for r in mine) / len(mine),
            "errors": sum(1 for r in mine if r.error),
            "cost": sum(r.cost for r in mine),
            "avg_latency_ms": sum(r.latency_ms for r in mine) / len(mine),
            "failed": [{"id": r.task_id, "why": r.error or "; ".join(r.reasons)} for r in mine if not r.passed],
        }
    return out

