"""GPU tier: provisioners, vLLM metrics, and the break-even state machine.

Lifecycle per self-hosted deployment (docs/05-gpu-autoscaling.md):

    api_only -> provisioning -> warm <-> draining -> api_only

The decision function is pure (``decide``) so it can be tested without clouds.
"""

from __future__ import annotations

import asyncio
import logging
import math
import os
import re
import shlex
import shutil
import tempfile
from dataclasses import dataclass, field
from pathlib import Path

import httpx
import yaml

from .classifier import parse_floor
from .config import BackendConfig, Config, ModelConfig, ServeConfig

log = logging.getLogger("meritorder.gpu")

API_ONLY, PROVISIONING, WARM, DRAINING = "api_only", "provisioning", "warm", "draining"


# ------------------------------------------------------------------ demand


@dataclass
class Demand:
    usd_per_hour: float  # what addressable traffic costs today, per hour
    tokens_per_second: float  # its throughput (peak of the 1h and 15m windows)


def addressable(model: ModelConfig, rows: list[dict], cfg: Config) -> tuple[float, int]:
    """Spend and tokens of traffic this model could have served (its quality meets the floor)."""
    cost, tokens = 0.0, 0
    for r in rows:
        floor = parse_floor(r.get("floor") or "")
        if floor is not None:
            ok = model.q(floor.task) >= floor.level
        else:
            requested = cfg.model(r.get("requested_model") or "")
            ok = (requested is not None and requested.name == model.name) or r.get("served_model") == model.name
        if ok:
            cost += r["cost"]
            tokens += r["tokens"]
    return cost, tokens


# ------------------------------------------------------------------ decisions


@dataclass
class Status:
    ready: bool = False
    endpoint: str | None = None
    failed: bool = False
    replicas: int = 0


@dataclass
class Action:
    kind: str  # "up" | "scale" | "down"
    replicas: int = 0


def desired_replicas(serve: ServeConfig, gpu_cost_per_hour: float, capacity_tps: float, demand: Demand) -> int:
    """Replicas worth running: enough for throughput, but each one must pay for itself."""
    by_load = math.ceil(demand.tokens_per_second / max(capacity_tps * serve.target_utilization, 1e-9)) if demand.tokens_per_second else 0
    if gpu_cost_per_hour > 0:
        affordable = math.floor(demand.usd_per_hour / (gpu_cost_per_hour * (1 + serve.margin)))
    else:
        affordable = serve.max_replicas
    want = min(max(by_load, 1 if affordable >= 1 else 0), affordable)
    return max(serve.min_replicas, min(serve.max_replicas, want))


def decide(rec: dict, serve: ServeConfig, desired: int, status: Status, now: float) -> tuple[dict, Action | None]:
    """Advance one deployment's state. Returns (new record, action to take)."""
    rec = dict(rec or {})
    state = rec.setdefault("state", API_ONLY)
    rec.setdefault("since", now)
    action: Action | None = None

    def move(new_state: str, why: str) -> None:
        rec.update(state=new_state, since=now, reason=why)
        log.info("deployment -> %s: %s", new_state, why)

    if state == API_ONLY:
        if desired >= 1 and now >= rec.get("cooldown_until", 0):
            rec.setdefault("over_since", now)
            if serve.min_replicas > 0 or now - rec["over_since"] >= serve.scale_up_after_minutes * 60:
                action = Action("up", desired)
                rec.update(replicas=desired, over_since=None)
                move(PROVISIONING, f"break-even for {desired} replica(s)")
        else:
            rec["over_since"] = None

    elif state == PROVISIONING:
        if status.ready and status.endpoint:
            rec["endpoint"] = status.endpoint
            move(WARM, "replicas ready")
        elif status.failed or now - rec["since"] > serve.provision_timeout_minutes * 60:
            action = Action("down")
            rec.update(endpoint=None, cooldown_until=now + 1800, replicas=0)
            move(API_ONLY, "provisioning failed or timed out; cooling down 30 min")

    elif state == WARM:
        if not status.ready:
            rec["endpoint"] = None
            move(PROVISIONING, "lost readiness")
        elif desired >= 1:
            rec["under_since"] = None
            rec["endpoint"] = status.endpoint
            if desired != rec.get("replicas"):
                action = Action("scale", desired)
                rec["replicas"] = desired
        else:
            rec.setdefault("under_since", None)
            rec["under_since"] = rec["under_since"] or now
            held = now - rec["since"] >= serve.hold_minutes * 60
            under = now - rec["under_since"] >= serve.scale_up_after_minutes * 60
            if held and under:
                move(DRAINING, "demand below break-even")

    elif state == DRAINING:
        if desired >= 1 and status.ready:
            rec["under_since"] = None
            move(WARM, "demand returned")
        elif now - rec["since"] >= serve.drain_minutes * 60:
            action = Action("down")
            rec.update(endpoint=None, replicas=0, under_since=None)
            move(API_ONLY, "drained")
    return rec, action


# ------------------------------------------------------------------ provisioners


def served_name(backend: BackendConfig, cfg: Config) -> str:
    serve = backend.serve
    assert serve is not None
    if serve.served_model_name:
        return serve.served_model_name
    model = cfg.model(serve.model)
    for r in model.routes if model else []:
        if r.backend == backend.name:
            return r.model
    return model.hf_id if model and model.hf_id else serve.model


async def _probe(endpoint: str) -> bool:
    try:
        async with httpx.AsyncClient(timeout=5) as c:
            r = await c.get(endpoint.rstrip("/") + "/models")
            return r.status_code == 200
    except httpx.HTTPError:
        return False


class StaticProvisioner:
    """A server you run yourself. Up/down are no-ops; readiness is probed."""

    def __init__(self, backend: BackendConfig, cfg: Config):
        self.backend = backend
        self.url = (backend.serve.static_url if backend.serve else None) or backend.base_url

    async def status(self) -> Status:
        if not self.url:
            return Status(failed=True)
        ready = await _probe(self.url)
        return Status(ready=ready, endpoint=self.url if ready else None, replicas=1 if ready else 0)

    async def up(self, replicas: int) -> None:
        log.info("%s: static deployment, nothing to start", self.backend.name)

    async def scale(self, replicas: int) -> None:
        return None

    async def down(self) -> None:
        log.info("%s: static deployment, nothing to stop", self.backend.name)


class SkyPilotProvisioner:
    """Runs vLLM on SkyServe. Needs the `sky` CLI installed and cloud credentials (`sky check`)."""

    def __init__(self, backend: BackendConfig, cfg: Config, workdir: Path | None = None):
        self.backend = backend
        self.cfg = cfg
        self.serve = backend.serve
        self.name = re.sub(r"[^a-z0-9-]", "-", f"meritorder-{backend.name}".lower())[:60]
        self.workdir = workdir or Path(os.environ.get("MERITORDER_STATE_DIR", Path(tempfile.gettempdir()) / "meritorder")) / "sky"
        self.endpoint: str | None = None

    def task_yaml(self, replicas: int) -> str:
        serve = self.serve
        model = self.cfg.model(serve.model)
        if model is None or not model.hf_id:
            raise ValueError(f"model {serve.model!r} needs an hf_id to self-host")
        gpus = int(serve.accelerators.split(":")[1]) if ":" in serve.accelerators else 1
        args = [
            "vllm", "serve", model.hf_id,
            "--host", "0.0.0.0", "--port", "8000",
            "--served-model-name", served_name(self.backend, self.cfg),
            "--tensor-parallel-size", str(gpus),
            "--enable-prefix-caching",
            "--scheduling-policy", "priority",
        ]
        run = " ".join(shlex.quote(a) for a in args) + (f" {serve.vllm_args}" if serve.vllm_args else "")
        resources: dict = {
            "accelerators": serve.accelerators,
            "use_spot": serve.use_spot,
            "ports": 8000,
            "disk_size": serve.disk_size_gb,
            "image_id": f"docker:{serve.image}",
        }
        if serve.clouds:
            resources["any_of"] = [{"cloud": c, **({"region": r} if r else {})} for c in serve.clouds for r in (serve.regions or [None])]
        task = {
            "name": self.name,
            "service": {
                "readiness_probe": {"path": "/v1/models", "initial_delay_seconds": serve.provision_timeout_minutes * 60},
                "replicas": max(replicas, 1),
            },
            "resources": resources,
            "envs": {"HF_TOKEN": ""},  # overridden with --env HF_TOKEN when set locally
            "run": run,
        }
        return yaml.safe_dump(task, sort_keys=False)

    async def _sky(self, *args: str) -> tuple[int, str]:
        if not shutil.which("sky"):
            raise RuntimeError("the `sky` CLI is not installed (pip install 'skypilot[aws,gcp,...]')")
        proc = await asyncio.create_subprocess_exec("sky", *args, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.STDOUT)
        out, _ = await proc.communicate()
        return proc.returncode or 0, out.decode(errors="replace")

    def _write(self, replicas: int) -> Path:
        self.workdir.mkdir(parents=True, exist_ok=True)
        path = self.workdir / f"{self.name}.yaml"
        path.write_text(self.task_yaml(replicas))
        return path

    async def up(self, replicas: int) -> None:
        path = self._write(replicas)
        env = ["--env", "HF_TOKEN"] if os.environ.get("HF_TOKEN") else []
        code, out = await self._sky("serve", "up", "-n", self.name, "-y", *env, str(path))
        if code:
            raise RuntimeError(f"sky serve up failed: {out[-800:]}")

    async def scale(self, replicas: int) -> None:
        path = self._write(replicas)
        code, out = await self._sky("serve", "update", self.name, "-y", str(path))
        if code:
            raise RuntimeError(f"sky serve update failed: {out[-800:]}")

    async def down(self) -> None:
        code, out = await self._sky("serve", "down", "-y", self.name)
        if code and "not found" not in out.lower():
            raise RuntimeError(f"sky serve down failed: {out[-800:]}")

    async def status(self) -> Status:
        try:
            code, out = await self._sky("serve", "status", "--endpoint", self.name)
        except RuntimeError:
            return Status(failed=True)
        m = re.search(r"(https?://)?(\d{1,3}(?:\.\d{1,3}){3}|[\w.-]+\.\w+):(\d+)", out)
        if code or not m:
            return Status()
        endpoint = f"{m.group(1) or 'http://'}{m.group(2)}:{m.group(3)}/v1"
        ready = await _probe(endpoint)
        return Status(ready=ready, endpoint=endpoint if ready else None)


def make_provisioner(backend: BackendConfig, cfg: Config):
    if backend.serve is None:
        raise ValueError(f"backend {backend.name} has no serve config")
    if backend.serve.provisioner == "static":
        return StaticProvisioner(backend, cfg)
    return SkyPilotProvisioner(backend, cfg)


# ------------------------------------------------------------------ vLLM metrics

_METRIC = re.compile(r"^(vllm:[a-z_]+)(?:\{[^}]*\})?\s+([0-9.eE+-]+)$", re.MULTILINE)


def parse_vllm_metrics(text: str) -> float:
    """Utilization in [0, 1]: KV-cache usage, pushed up when requests are queueing."""
    values: dict[str, float] = {}
    for name, value in _METRIC.findall(text):
        try:
            values[name] = values.get(name, 0.0) + float(value)
        except ValueError:
            continue
    kv = values.get("vllm:kv_cache_usage_perc", values.get("vllm:gpu_cache_usage_perc", 0.0))
    waiting = values.get("vllm:num_requests_waiting", 0.0)
    util = min(kv, 1.0)
    if waiting > 0:
        util = max(util, min(1.0, 0.85 + 0.015 * waiting))
    return util


async def fetch_utilization(endpoint: str) -> float | None:
    base = endpoint.rstrip("/")
    base = base[:-3] if base.endswith("/v1") else base
    try:
        async with httpx.AsyncClient(timeout=5) as c:
            r = await c.get(f"{base}/metrics")
        return parse_vllm_metrics(r.text) if r.status_code == 200 else None
    except httpx.HTTPError:
        return None


@dataclass
class Deployment:
    backend: BackendConfig
    model: ModelConfig
    provisioner: object
    record: dict = field(default_factory=dict)

